adjustmentBlocks.push(
 h('Горе и адаптация к утрате близкого'),
 h('Терминология',3),
 p('Хотя английские слова bereavement, mourning и grief иногда употребляют как взаимозаменяемые, они имеют разные значения, отражающие полезные для психиатрии различия.'),
 list([
  'Утрата близкого (bereavement) — потеря любимого человека вследствие его смерти.',
  'Горе (grief) — непроизвольная эмоциональная и поведенческая реакция на утрату близкого.',
  'Траур (mourning) — произвольное выражение поведения и исполнение ритуалов, представляющих социально одобряемые реакции на утрату. Их форма и продолжительность различаются между обществами и религиозными группами.'
 ]),
 p('В классификационных системах эти различия проводятся непоследовательно. В МКБ-11 неосложнённая утрата близкого соответствующим образом кодируется как QE.62, то есть как один из «факторов, влияющих на состояние здоровья и обращение в службы здравоохранения». В DSM-5 сама утрата не кодируется, однако «стойкое комплексное расстройство, связанное с утратой близкого» — тяжёлая реакция горя, сохраняющаяся не менее 12 месяцев, — включено в раздел «Состояния для дальнейшего изучения». Таким образом, термин используется для обозначения реакции на утрату, а не самого события. МКБ-11 кодирует горе в рамках расстройств адаптации, используя термин «пролонгированное расстройство горя». Траур — форма социального поведения — не является расстройством и закономерно отсутствует в указателях обеих классификаций. В этой главе термин «реакция на утрату близкого» обозначает все реакции на утрату — нормальные и патологические. Нормальные реакции называются горем, а патологические включают патологическое горе, также называемое осложнённым или комплексным горем, депрессивные расстройства и расстройства адаптации.'),
 h('Горе',3),
 p('Горе — непрерывный процесс, но для ясности в нём можно описать три стадии (см. вставку 7.8).'),
 p('Первая стадия длится от нескольких часов до нескольких дней. Отрицание проявляется отсутствием эмоциональной реакции — «оцепенением», — часто сопровождающимся ощущением нереальности происходящего и неполным принятием факта смерти. Человек может быть беспокоен, словно разыскивает умершего.'),
 p('Вторая стадия обычно продолжается от нескольких недель до примерно шести месяцев, но может быть значительно дольше. Возможны крайняя печаль, плач, одиночество и часто захлёстывающие волны тоски по умершему. Распространена тревога: человек тревожен и беспокоен, плохо спит, теряет аппетит, у него могут возникать панические приступы. Многие испытывают вину, считая, что сделали для умершего недостаточно. Некоторые испытывают гнев и проецируют чувство вины, обвиняя врачей или других людей в том, что те не обеспечили умершему наилучшую помощь. Многие ярко ощущают присутствие умершего; примерно у одного из десяти возникают кратковременные галлюцинации. Человек поглощён воспоминаниями об умершем, иногда в форме навязчиво возникающих образов. Часто наблюдаются уход от социальных отношений и жалобы на соматические симптомы.'),
 p('На третьей стадии эти симптомы ослабевают, и повседневная деятельность возобновляется. Человек постепенно примиряется с утратой и вспоминает хорошие времена, проведённые с умершим. В годовщину смерти симптомы нередко временно возвращаются.'),
 p('Хотя эти стадии полезны как ориентир, индивидуальные реакции различаются, и ни один признак не является универсальным. Более того, переживания могут быть сложнее: строгое ожидание последовательного прохождения стадий, несмотря на теоретическую привлекательность, может причинять страдание, если переживания не развиваются линейно (Avis et al., 2021).'),
 box('Вставка 7.8. Нормальная реакция горя',[
  h('Стадия 1: часы — дни',3),
  list(['Отрицание, шок, неверие.','«Оцепенение».']),
  h('Стадия 2: недели — шесть месяцев',3),
  list(['Печаль, плач, волны горя.','Соматические симптомы тревоги.','Беспокойство.','Плохой сон.','Снижение аппетита.','Вина, обвинение других.','Ощущение присутствия.','Иллюзии, яркие образы.','Галлюцинации голоса умершего.','Поглощённость воспоминаниями об умершем.','Социальное отстранение.']),
  h('Стадия 3: недели — месяцы',3),
  list(['Ослабление переживаний горя.','Возобновление социальной активности.','Воспоминания о хороших временах.','В годовщины симптомы могут возвращаться.'])
 ]),
 h('Патологическое горе',3),
 p('Горе считают патологическим, если оно отсрочено или подавлено либо необычно интенсивно и продолжительно; в последнем случае его называют осложнённым или патологическим. Обычный критерий отсрочки — отсутствие первой стадии горя спустя две недели после смерти. Критерий патологической продолжительности — сохранение реакции более шести месяцев. Однако многие горюют дольше, и необходима клиническая оценка того, продолжают ли чувства горя разрешаться, пусть и медленно. При всех формах патологического горя часто наблюдается стойкое избегание ситуаций и других напоминаний о смерти.'),
 h('Депрессия в ходе реакции горя',4),
 p('Депрессивные симптомы часто входят в нормальное горе; примерно 30% людей, переживших утрату, в какой-то момент горевания отвечают критериям депрессивного расстройства. Большинство таких расстройств разрешается в течение шести месяцев, но около 20% сохраняется дольше. Можно возразить, что, если примерно треть переживших утрату в какой-то момент соответствует критериям депрессивного расстройства, диагностический порог установлен слишком низко. Однако люди, соответствующие этим критериям, чаще плохо адаптируются социально, часто обращаются к врачам и употребляют алкоголь. Кроме того, им могут помогать лекарства и психотерапия, применяемые при депрессии. Поэтому использование этого критерия и регистрация дополнительного диагноза депрессивного расстройства имеют практическую ценность.'),
 p('Если есть сомнение, следует ли регистрировать депрессивное расстройство, особое внимание нужно уделить заторможенности, глобальному снижению самооценки и вине — явно более интенсивной, чем обычные сожаления об упущениях в уходе во время терминальной болезни. Эти признаки редко встречаются при неосложнённом горе. Важно также выяснять наличие суицидальных переживаний. При осложнённом горе суицидальные мысли обычно связаны с желанием соединиться с умершим, тогда как при депрессии желание умереть сопровождается всеобъемлющим чувством безнадёжности.'),
 h('Осложнённое горе',4),
 p('Осложнённое горе возникает примерно у 10% переживших утрату (Szuhany et al., 2021). Для него характерна интенсивная и длительная реакция на смерть близкого. Она может включать сильную тоску по умершему и мысль о том, что теперь жизнь лишена всякой цели и смысла. Возникают неверие в случившуюся смерть и гнев; напоминаний об утрате избегают или, напротив, постоянно ищут их в ущерб другим занятиям и отношениям. Осложнённое горе также связано с нарушениями сна, увеличением употребления психоактивных веществ и ухудшением профессионального и социального функционирования. Многие из этих признаков отражены в категории DSM-5 «стойкое комплексное расстройство, связанное с утратой близкого», хотя необходимая продолжительность горя после утраты здесь составляет 12 месяцев, а не шесть месяцев, предусмотренных диагнозом пролонгированного расстройства горя в МКБ-11. В DSM-5-TR это состояние, как и в МКБ-11, относится к категории пролонгированного расстройства горя.'),
 h('Причины патологического горя',3),
 p('Обычно считают, что патологическое горе вероятнее при следующих обстоятельствах:'),
 list([
  'Смерть была внезапной и неожиданной.',
  'Отношения пережившего утрату с умершим были очень близкими, зависимыми или амбивалентными.',
  'Переживший утрату не уверен в себе, с трудом выражает чувства или ранее страдал психическим расстройством.',
  'Переживший утрату должен заботиться о зависимых от него детях и потому не может свободно проявлять горе.'
 ]),
 h('Заболеваемость после утраты близкого'),
 p('Несколько исследований, систематически рассмотренных Ennis and Majid (2021), показали повышение смертности среди переживших утрату супругов и других близких родственников, наиболее выраженное в первые шесть месяцев. В большинстве исследований отмечалась повышенная смертность от сердечных заболеваний, а в некоторых — от рака, цирроза печени, суицида и несчастных случаев. Причины этих связей неясны и, вероятно, различаются для разных состояний.'),
 h('Помощь при горе'),
 p('Горе — нормальная реакция, и большинство людей переживает его с помощью семьи, друзей, духовных наставников и траурных ритуалов. В некоторых западных обществах у многих людей нет связи с религией, траурные ритуалы могут быть ослаблены, а семья — находиться далеко. По этим и другим причинам семейным врачам принадлежит важная роль в помощи пережившим утрату. Психиатров могут просить помочь людям с патологическим горем.'),
 p('Хотя у переживших утрату есть общие проблемы, существуют и индивидуальные. Например, у молодой вдовы с маленькими детьми будет много трудностей, которых нет у пожилой вдовы, получающей поддержку взрослых детей. У матери, горюющей о мертворождённом ребёнке, будут особые проблемы (см. ниже). Планируя помощь, важно учитывать индивидуальные обстоятельства пациента наряду с общими принципами, изложенными ниже.'),
 p('Стратегии совладания, ритуалы и ожидания различаются между религиозными и культурными группами; при решении, что может помочь, их необходимо деликатно исследовать и понимать. Подробнее о культурных и глобальных перспективах горя см. Smid et al. (2018).'),
 h('Консультирование',3),
 p('Когда консультирование показано, оно сходно с консультированием при других адаптационных реакциях. Пережившему утрату нужно говорить о потере, выражать печаль, вину или гнев и понимать нормальный ход горевания. Полезно заранее предупредить о необычных переживаниях, например ощущении присутствия умершего, иллюзиях и галлюцинациях: иначе они могут испугать человека. Помощь может понадобиться для того, чтобы:'),
 list(['Признать реальность утраты.','Пройти через стадии горя.','Адаптироваться к жизни без умершего.']),
 p('Пережившему утрату может понадобиться помощь для перехода от первой стадии отрицания потери к принятию реальности. Увидеть тело умершего и убрать его вещи помогает этому переходу, и человека следует побуждать к таким действиям. Может потребоваться обсуждение практических проблем, включая организацию похорон и финансовые трудности. Молодой вдове может быть нужна помощь в уходе за маленькими детьми и их поддержке без чрезмерного подавления собственного горя. По мере того как проходит время, пережившего утрату следует поощрять возобновлять социальные контакты, говорить с другими о потере, вспоминать счастливые и наполненные смыслом переживания, разделённые с умершим, и задумываться о положительных занятиях, которых умерший пожелал бы оставшимся в живых. Дополнительные сведения о психологических вмешательствах при горе см. Johannsen et al. (2019).'),
 p('Родителям, горюющим о мертворождённом ребёнке, нужна особая помощь. Мертворождение связано с повышенной частотой депрессии и состояний, связанных с травмой, у родителей (Westby et al., 2021). Прежде было принято рекомендовать физический контакт с мертворождённым ребёнком; понятно, что многие родители этого хотят. Однако растёт число данных о связи удерживания тела ребёнка на руках с повышенным риском неблагоприятных психологических исходов, поэтому нынешняя рекомендация состоит в том, чтобы родители не видели тело и не держали его на руках, если сами не выразят такое желание (Sun et al., 2023). Мертворождение повышает риск последующего распада отношений; отсутствие поддержки партнёра во время мертворождения и удерживание мертворождённого ребёнка на руках увеличивают этот риск.'),
 h('Лекарственное лечение',3),
 p('Лекарства не могут устранить страдание при нормальном горе, но могут потребоваться в определённых обстоятельствах. На первой стадии горя на несколько дней может понадобиться снотворное или анксиолитик для восстановления сна или облегчения сильной тревоги. На второй стадии антидепрессанты могут быть полезны при выполнении критериев депрессивного расстройства, хотя их применение именно в этой группе изучено недостаточно широко. Иногда антидепрессанты могут помогать и при осложнённом горе, но их лучше использовать вместе со структурированной психотерапией.'),
 h('Группы поддержки',3),
 p('Группы поддержки созданы для помощи недавно пережившим утрату, особенно молодым вдовам и вдовцам. Одна из таких организаций в Великобритании называется Cruse. Общаясь с людьми, успешно справившимися с утратой, недавно потерявшие близкого могут разделить своё горе с другими, получить практические советы и обсудить способы совладания.'),
 h('Психотерапия',3),
 p('Предоставлять структурированную психотерапию большинству переживших утрату практически неосуществимо, и данных о её пользе для всех этих людей нет. При патологическом горе динамическая психотерапия имеет ясное обоснование и подход, но её эффективность формально не оценивалась. Однако сообщалось, что терапия осложнённого горя (complicated grief treatment, CGT), сочетающая элементы КПТ и интерперсональной терапии, полезна при патологическом горе и более эффективна, чем интерперсональная терапия или лечение СИОЗС циталопрамом (Szuhany et al., 2021).'),
 p('CGT делает акцент на создании повествования об утрате, включающего саму смерть близкого, а также положительные и отрицательные стороны жизни с умершим. Психообразование о горе и его осложнениях дополняется экспозицией к тем аспектам утраты, которых человек избегает. Применяют и когнитивную реструктуризацию для переоценки дезадаптивных мыслей — например, убеждения, что горевание является единственным способом почтить умершего. Некоторые техники CGT доступны неспециалистам: например, обсуждение утраты и прежних отношений с умершим, а также совет не избегать таких событий, как семейные встречи, которые будут напоминать о человеке и его потере (Szuhany et al., 2021).')
);
adjustmentBlocks.push(
 h('Отдалённая адаптация после сексуального насилия в детстве'),
 p('После сексуального насилия у детей могут возникать нарушения во многих сферах жизни: в семье, в отношениях со сверстниками и взрослыми, а также в образовании. Они также подвержены риску тревоги, депрессии и ПТСР. Эти последствия могут сохраняться во взрослом возрасте; наиболее сильные психиатрические связи выявлены с конверсионным расстройством, пограничным расстройством личности, тревогой и депрессией. Кроме того, сексуальное насилие в детстве может сопровождаться стойкой низкой самооценкой и психосексуальными трудностями независимо от развития психического расстройства (Hailes et al., 2019).'),
 p('Очень редко взрослые, подвергавшиеся сексуальному насилию в детстве, но не вспоминающие активно его подробности, могут внезапно вспомнить насилие либо столкнуться с напоминанием о нём в яркой, тревожащей форме. Иногда это происходит спонтанно, часто после встречи с чем-либо, напоминающим о событиях. Воспоминания могут возникать и при консультировании или психотерапии, когда обсуждаются детские переживания. Некоторые из них подтверждаются другими данными, но зачастую, особенно спустя длительное время, получить дополнительные свидетельства насилия трудно. Это может усиливать страдание, особенно если предполагаемые виновники отрицают обвинения. Высказывалось также предположение, что некоторые неподтверждённые сообщения о насилии представляют собой неточные воспоминания, а часть из них вызвана вопросами, внушениями или интерпретациями терапевтов. Это явление получило название «синдром ложной памяти» (Brewin, 2009).'),
 h('Восстановленные и ложные воспоминания',3),
 p('У переживших сексуальное насилие и другие тяжёлые стрессовые события может быть частичная амнезия наиболее стрессовых фрагментов пережитого, хотя травмы головы, способной вызвать посттравматическую амнезию, не было. Частичная амнезия действительно входит в клиническую картину ПТСР. Однако полная амнезия встречается реже; по мнению многих психиатров, полная амнезия повторных стрессовых событий с последующим их воспоминанием маловероятна, особенно при отсутствии подтверждения событий из другого источника. Эти сомнения усиливаются данными о том, что примерно у 30% испытуемых можно посредством внушения сформировать «воспоминания» об отдельных детских событиях, не связанных с насилием (Scoboria et al., 2017).'),
 p('Свидетельства в пользу того, что подлинные воспоминания могут оставаться недоступными многие годы, а затем восстанавливаться, происходят главным образом из клинических сообщений. Они позволяют предположить, что около 25–50% людей, сообщающих о сексуальном насилии в детстве, описывают длительные периоды, когда не помнили о нём. Кроме того, клинические исследования показали, что около 20–60% сообщающих о таком насилии утверждают, что в их жизни были периоды, когда они не могли вспомнить, что оно происходило. Некоторые люди восстанавливали воспоминания о насилии до начала терапии, поэтому в этих случаях терапевтическое внушение не могло оказать влияние.'),
 p('При отсутствии убедительных данных о статусе воспоминаний, восстановленных во время консультирования или психотерапии, проводящий их клиницист должен:'),
 list(['Особенно тщательно избегать внушения воспоминаний о сексуальном насилии.','Очень внимательно оценивать предположительно восстановленные воспоминания, впервые возникшие во время терапии, прежде чем заключать, что это подлинные воспоминания о реальных событиях.']),
 p('Состояние современных научных данных указывает на необходимость непредвзятого отношения к возможности и вероятной частоте восстановленных воспоминаний о сексуальном насилии и, разумеется, о других травматических переживаниях. Обзор см. Otgaar et al. (2022).'),
 h('Эпидемиология',3),
 p('У взрослых, сообщающих о сексуальном насилии в детстве, частота психических расстройств во взрослом возрасте выше. Неясно, какая доля детей, подвергшихся насилию, впоследствии развивает такие расстройства; некоторые, по-видимому, хорошо адаптируются. Важным фактором этой устойчивости является наличие хотя бы некоторых качественных отношений в детстве и подростковом возрасте (Fuller-Thompson et al., 2020).'),
 p('В австралийском проспективном исследовании более 2750 детей, подвергшихся сексуальному насилию, 80% из которых были женского пола, наблюдали до 40 лет. Cutajar et al. (2010) установили, что впоследствии 24% этой группы обращались в службы психического здоровья по сравнению с 8% контрольной группы. У переживших насилие была выше частота ряда психических расстройств взрослого возраста, особенно ПТСР, расстройств, связанных с употреблением психоактивных веществ, и расстройств личности; также повышался риск расстройств настроения, тревожных расстройств и психоза. Более тяжёлое сексуальное насилие и более старший возраст на момент его совершения были значимыми предикторами психического расстройства во взрослом возрасте. Зонтичный обзор последствий сексуального насилия в детстве для психического здоровья взрослых пришёл к сходному выводу (Hailes et al., 2019).'),
 p('Chen et al. (2014) изучили более 6000 женщин ханьской этнической группы в Китае с рекуррентной большой депрессией и сходное число здоровых участниц контрольной группы. Любая сообщаемая форма сексуального насилия в детстве была связана с четырёхкратным повышением риска рекуррентной депрессии; риск возрастал с тяжестью насилия. Насилие также было связано с суицидальностью, чувством вины и собственной никчёмности.'),
 h('Этиология',3),
 p('Сексуальное насилие в детстве может непосредственно обусловливать уязвимость к психическому расстройству во взрослом возрасте либо быть маркером другого фактора, например нарушенных отношений в семье, который является основной причиной повышенной частоты этих расстройств. В частности, стало ясно, что сексуальное насилие часто сосуществует и потому тесно коррелирует с другими неблагоприятными обстоятельствами детства: иными формами жестокого обращения — физическим и эмоциональным насилием, пренебрежением нуждами ребёнка; утратой родителей вследствие смерти или иных форм разлучения, например развода; неблагополучием родителей — насилием, преступностью, злоупотреблением психоактивными веществами и психическими заболеваниями. Поэтому исследования влияния одной формы детского неблагополучия на риск психического расстройства взрослого возраста могут переоценивать влияние именно этой формы. Более современные исследования измеряют ряд неблагоприятных обстоятельств, затем используют многомерное моделирование для оценки относительного значения разных видов неблагополучия и того, насколько их влияние на последующий риск является суммирующимся, а не общим.'),
 p('В систематическом обзоре 96 исследований отдалённого влияния жестокого обращения в детстве на психическое здоровье Gardner et al. (2019) обнаружили, что несколько его форм — сексуальное, физическое и эмоциональное насилие, пренебрежение нуждами ребёнка и наблюдение насилия между интимными партнёрами — повышали риск последующих тревожных и депрессивных расстройств и ПТСР. Среди разных форм жестокого обращения сексуальное насилие было наиболее сильным предиктором тревожных расстройств и ПТСР. Неблагоприятные последствия для психического здоровья усиливались по мере увеличения числа форм жестокого обращения, пережитых ребёнком.'),
 h('Лечение',3),
 p('Для лечения отдалённых последствий сексуального насилия в детстве применяли консультирование, динамическую психотерапию, когнитивную терапию и групповые методы. У разных методов есть несколько общих особенностей:'),
 list(['Общая цель — помочь пациенту понять прежние переживания и их влияние на его жизнь, чтобы улучшить нынешнюю адаптацию.','Терапевтические отношения помогают пациенту почувствовать, что ему доверяют, его понимают и уважают, и повысить самооценку.','Пациенту позволяют самому задавать темп рассказа о насилии; иначе воспоминания могут вызвать чрезмерно сильную эмоциональную реакцию и привести к прекращению лечения.','Выявляют текущие проблемы адаптации, особенно избегание проблем и трудности выражения гнева, и помогают преодолеть эти трудности.','Некоторым пациентам нужна помощь с психосексуальными проблемами.']),
 p('Основное различие динамического и когнитивно-поведенческого подходов заключается в том, что первый больше подчёркивает понимание влияния травмы на самооценку и выражение эмоций, а второй — более точное определение того, как нынешние способы мышления влияют на текущее поведение. В метаанализе 44 исследований Taylor and Harvey (2010) обнаружили, что многие разные психологические методы, от групповой аналитической терапии до индивидуальной КПТ, давали умеренную пользу в отношении ряда симптомов у взрослых, перенёсших сексуальное насилие в детстве. В целом наибольшая величина эффекта отмечалась при КПТ, особенно для симптомов ПТСР. Для многих пациентов будут актуальны методы, разрабатываемые для комплексного ПТСР — см. выше.')
);
